const repos = $input.first().json.items || [];
const top5 = repos
  .slice()
  .sort((a, b) => b.stargazers_count - a.stargazers_count)
  .slice(0, 5)
  .map((r) => ({
    owner: r.owner.login,
    name: r.name,
    fullName: r.full_name,
    stars: r.stargazers_count,
    url: r.html_url,
    description: r.description || '',
  }));
if (top5.length === 0) {
  throw new Error('GitHub returned no repositories');
}
const topRepo = top5[0];
const lines = top5.map((r, i) => (i + 1) + '. ' + r.fullName + ' (' + r.stars + ' stars)\n   ' + r.url + '\n   ' + r.description);
const digestText = 'Top 5 JavaScript repositories on GitHub:\n\n' + lines.join('\n\n');
return [{ json: { top5, topRepo, digestText } }];

const src = $('Select Top 5').first().json;
const raw = String($input.first().json.readme || '');

function cleanReadme(text) {
  let t = text.replace(/\r\n?/g, '\n');
  t = t.replace(/<!--[\s\S]*?-->/g, ' ');
  t = t.replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ');
  t = t.replace(/```[^\n]*\n[\s\S]*?```/g, ' ');
  t = t.replace(/!\[[^\]]*\]\([^)]*\)/g, ' ');
  t = t.replace(/!\[[^\]]*\]\[[^\]]*\]/g, ' ');
  t = t.replace(/\[!\[[^\]]*\]\([^)]*\)\]\([^)]*\)/g, ' ');
  t = t.replace(/<img[^>]*>/gi, ' ');
  t = t.replace(/<br\s*\/?>/gi, '\n');
  t = t.replace(/<\/(p|div|h[1-6]|li|tr|table|ul|ol|details|summary)>/gi, '\n\n');
  t = t.replace(/<[^>]+>/g, ' ');
  t = t.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
  t = t.replace(/\[([^\]]+)\]\[[^\]]*\]/g, '$1');
  t = t.replace(/^\s*\[[^\]]+\]:\s*\S+.*$/gm, '');
  t = t.replace(/^\s{0,3}#{1,6}\s*/gm, '');
  t = t.replace(/^\s*[-*_=]{3,}\s*$/gm, '');
  t = t.replace(/^\s*\|?[\s:|-]{3,}\|?\s*$/gm, '');
  t = t.replace(/^\s*>\s?/gm, '');
  t = t.replace(/^\s*[-*+]\s+/gm, '- ');
  t = t.replace(/(\*\*|__)(.*?)\1/g, '$2');
  t = t.replace(/(\*|_)(\S[^*_\n]*\S|\S)\1/g, '$2');
  t = t.replace(/`([^`]*)`/g, '$1');
  t = t.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  t = t.replace(/\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\]/gi, '');
  t = t.split('\n').filter((l) => (l.match(/\|/g) || []).length < 3 && !/^\s*(\*|_)*(languages?|translations?|translated|available in|read this in|read in|idiomas?|langues?)(\*|_)*\s*[:\-]/i.test(l) && !/(\s[|·•]\s).*(\s[|·•]\s)/.test(l)).join('\n');
  t = t.replace(/[ \t]+/g, ' ');
  t = t.split('\n').map((l) => l.trim()).join('\n');
  t = t.replace(/\n{3,}/g, '\n\n').trim();
  return t;
}

function excerpt(text, max) {
  const paras = text.split(/\n\n+/).map((p) => p.replace(/\n/g, ' ').trim()).filter((p) => p.length >= 20 && (p.match(/\|/g) || []).length < 3 && !/^(\*|_)*(languages?|translations?|available in|read this in)(\*|_)*\s*[:\-]/i.test(p));
  let out = '';
  for (const p of paras) {
    if (out.length >= max) break;
    out += (out ? '\n\n' : '') + p;
  }
  if (out.length > max) {
    out = out.slice(0, max);
    const cut = Math.max(out.lastIndexOf('. '), out.lastIndexOf(' '));
    if (cut > max * 0.6) out = out.slice(0, cut);
    out = out.replace(/[\s,;:.-]+$/, '') + '...';
  }
  return out;
}

const readmeExcerpt = excerpt(cleanReadme(raw), 800) || 'No readable README text was available.';
const fmt = (n) => Number(n).toLocaleString('en-US');
const line = '------------------------------------------------------------';
const repoBlocks = src.top5.map((r, i) =>
  (i + 1) + '. ' + r.fullName + '\n' +
  '   Stars: ' + fmt(r.stars) + '\n' +
  '   Link: ' + r.url + '\n' +
  '   About: ' + (r.description || 'No description provided')
);
const top = src.topRepo;
const emailBody =
  'GITHUB TRENDING - TOP 5 JAVASCRIPT REPOSITORIES\n' +
  'Generated: ' + $now.toFormat('dd LLL yyyy, HH:mm') + '\n' +
  line + '\n\n' +
  repoBlocks.join('\n\n') + '\n\n' +
  line + '\n' +
  'TOP REPOSITORY SPOTLIGHT: ' + top.fullName + ' (' + fmt(top.stars) + ' stars)\n' +
  line + '\n\n' +
  'README excerpt:\n' + readmeExcerpt + '\n\n' +
  'Full README: ' + top.url + '#readme\n';
return [{ json: { emailBody, readmeExcerpt } }];
